(() => {
    const REFRESH_MS = 30000;
    const BYTES_PER_GIB = 1024 ** 3;
    const PERCENT = 100;
    let ready = false;
    let busy = false;
    const text = (id, value) => { document.getElementById(id).textContent = value; };
    const bytes = value => Number.isFinite(value) && value >= 0 ? (value / BYTES_PER_GIB).toFixed(1) + " GiB" : "Unavailable";
    async function refresh() {
        if (!ready || busy || !selfWidget.visible || document.hidden) return;
        busy = true;
        document.getElementById("refresh").disabled = true;
        try {
            const state = await dikciz.command("deviceState");
            text("battery", Number.isFinite(state.batteryLevel) && state.batteryLevel >= 0 && state.batteryScale > 0 ? Math.round(state.batteryLevel * PERCENT / state.batteryScale) + "%" : "Unavailable");
            text("storage", bytes(state.system?.storage?.availableBytes));
            text("ram", bytes(state.system?.memory?.availableBytes));
            text("network", state.vpn ? "VPN" : state.wifi ? "Wi-Fi" : state.cellular ? "Mobile" : state.networkAvailable ? "Network" : "Offline");
            text("power", (state.chargingSource > 0 ? "Charging" : "On battery") + (state.powerSaveMode ? ". Battery saver on." : ". Battery saver off."));
            text("status", "Updated " + new Date().toLocaleTimeString() + ". Storage is the app-data filesystem. Refreshes every 30 seconds while visible.");
        } catch (error) { text("status", "Device refresh failed: " + error.message + ". Previous values may be stale."); }
        finally { busy = false; document.getElementById("refresh").disabled = false; }
    }
    document.getElementById("refresh").addEventListener("click", refresh);
    window.addEventListener("dikciz-ready", () => { ready = true; refresh(); });
    window.addEventListener("dikciz-visibility", refresh);
    document.addEventListener("visibilitychange", refresh);
    setInterval(refresh, REFRESH_MS);
})();

scripts.source:
local LOW_LEVEL = 20
local RESET_LEVEL = 30
local CHARGING = 2
local FULL = 5
function on_event(event)
  local level = event.payload.level
  local status = event.payload.status
  if event.type ~= "battery" or type(level) ~= "number" or level < 0 or level > 100 then
    return { status = "Waiting for battery data" }
  end
  if level >= RESET_LEVEL or status == CHARGING or status == FULL then
    return { status = "Reminder reset", actions = { { type = "patchState", values = { alerted = false } } } }
  end
  if level > LOW_LEVEL or context.state.alerted then
    return { status = "No reminder needed" }
  end
  if not context.androidAccess.notificationPosting then
    return { status = "Allow Android notifications in Automation settings first" }
  end
  return { status = "Low battery reminder requested", actions = {
    { type = "patchState", values = { alerted = true } },
    { type = "postNotification", title = "Battery is low", text = tostring(level) .. "% remaining. Time to charge." }
  } }
end

local READY_LEVEL = 80
local RESET_LEVEL = 75
local CHARGING = 2
local FULL = 5
function on_event(event)
  local level = event.payload.level
  local status = event.payload.status
  if event.type ~= "battery" or type(level) ~= "number" or level < 0 or level > 100 then
    return { status = "Waiting for battery data" }
  end
  if level < RESET_LEVEL or (status ~= CHARGING and status ~= FULL) then
    return { status = "Reminder reset", actions = { { type = "patchState", values = { alerted = false } } } }
  end
  if level < READY_LEVEL or context.state.alerted then
    return { status = "No reminder needed" }
  end
  if not context.androidAccess.notificationPosting then
    return { status = "Allow Android notifications in Automation settings first" }
  end
  return { status = "Charging reminder requested", actions = {
    { type = "patchState", values = { alerted = true } },
    { type = "postNotification", title = "Charged enough", text = tostring(level) .. "% charged. You can unplug your phone." }
  } }
end

function on_event(event)
  if event.type ~= "manual" then return { status = "Run manually to lock the screen" } end
  if not context.androidAccess.deviceAdminActive then
    return { status = "Enable Device Administration in Automation settings first" }
  end
  return { status = "Lock requested", actions = { { type = "lockDevice" } } }
end
